Author: jeanlf <jeanlf@gpac.io>
Date:   Fri Mar 12 20:05:38 2021 +0100

    do not abort if Xtra parsing fails - cf #1707

diff --git a/include/gpac/internal/isomedia_dev.h b/include/gpac/internal/isomedia_dev.h
index 87541a44e..1bd19d2f6 100644
--- a/include/gpac/internal/isomedia_dev.h
+++ b/include/gpac/internal/isomedia_dev.h
@@ -597,6 +597,14 @@ typedef struct
                }\
                __ptr->size -= bytes; \

+
+#define ISOM_DECREASE_SIZE_NO_ERR(__ptr, bytes)        if (__ptr->size < (bytes) ) {\
+                       GF_LOG(GF_LOG_WARNING, GF_LOG_CONTAINER, ("[isom] not enough bytes in box %s: %d left, reading %d (file %s, line %d), skipping box\n", gf_4cc_to_str(__ptr->type), (u32) __ptr->size, (bytes), __FILE__, __LINE__ )); \
+                       return GF_OK; \
+               }\
+               __ptr->size -= bytes; \
+
+
 /*constructor*/
 GF_Box *gf_isom_box_new(u32 boxType);
 //some boxes may have different syntax based on container. Use this constructor for this case
diff --git a/src/isomedia/box_code_base.c b/src/isomedia/box_code_base.c
index e7e7adba6..0fecb902b 100644
--- a/src/isomedia/box_code_base.c
+++ b/src/isomedia/box_code_base.c
@@ -12432,12 +12432,12 @@ GF_Err xtra_box_read(GF_Box *s, GF_BitStream *bs)
                u32 prop_type = 0;

                char *data=NULL, *data2=NULL;
-               ISOM_DECREASE_SIZE(ptr, 18)
+               ISOM_DECREASE_SIZE_NO_ERR(ptr, 18)
                s32 tag_size = gf_bs_read_u32(bs);
                u32 name_size = gf_bs_read_u32(bs);
                tag_size -= 8;

-               ISOM_DECREASE_SIZE(ptr, name_size)
+               ISOM_DECREASE_SIZE_NO_ERR(ptr, name_size)
                data = gf_malloc(sizeof(char) * (name_size+1));
                gf_bs_read_data(bs, data, name_size);
                data[name_size] = 0;
@@ -12451,7 +12451,7 @@ GF_Err xtra_box_read(GF_Box *s, GF_BitStream *bs)
                        tag_size-=2;
                        prop_type = gf_bs_read_u16(bs);
                        prop_size -= 6;
-                       ISOM_DECREASE_SIZE(ptr, prop_size)
+                       ISOM_DECREASE_SIZE_NO_ERR(ptr, prop_size)
                        data2 = gf_malloc(sizeof(char) * (prop_size));
                        gf_bs_read_data(bs, data2, prop_size);
                        tag_size-=prop_size;
